import{_ as i,l as o,o as e,c as n,v as t,p as s,x as r,d as p,i as d,S as h}from"./chunks/framework.InCnrqk-.js";const B=JSON.parse('{"title":"过度思考","description":"","frontmatter":{"title":"过度思考","date":"2026-09-08T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/overthinking.md","filePath":"llm/overthinking.md","lastUpdated":1789023840000}'),E={name:"llm/overthinking.md"};function c(m,a,A,_,u,f){const l=o("Mermaid");return e(),n("div",null,[a[1]||(a[1]=t('<h1 id="过度思考" tabindex="-1">过度思考 <a class="header-anchor" href="#过度思考" aria-label="Permalink to &quot;过度思考&quot;">​</a></h1><div class="epigraph"><p>简单题上继续写「等等、再验一遍」，准确率不涨，延迟先涨；这是对错奖励没有长度价格时的理性行为。</p><footer>—— 对照 Chen 等对推理模型过度思考的测量；R1 长度随训练增长的现象</footer></div><p><a href="/llm/hybrid-thinking-mode">上一课</a>希望简单题走短模式。若路由失败或没有短模式，模型会在已经会的题上循环自检。缺口是：<strong>终局 \\(R\\) 对「更快做对」零奖励，探索到的长链一旦曾经有用，就被固定成默认。</strong> 本课写过度思考的诊断与抑制，接到长度控制。不把「想得少」写成普遍更智能。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>Chen 等人（及后续测量）观察到：推理模型在容易的 GSM 级题上仍生成极长链，pass@1 相对短 CoT 增益很小，token 费用大。R1-Zero 长度上涨是组内长链更容易得 \\(R=1\\)。没有负的长度项，最优是写到上限附近再停。过度思考 = 边际准确率 ≈ 0 的那一段生成。</p><p>自检循环（「wait, let me recheck」多次）是典型表面。它与后课有用的回溯不同：有用回溯改变答案；过度思考重复同一答案。</p><h3 id="不要用平均长度当唯一-kpi" tabindex="-1">不要用平均长度当唯一 KPI <a class="header-anchor" href="#不要用平均长度当唯一-kpi" aria-label="Permalink to &quot;不要用平均长度当唯一 KPI&quot;">​</a></h3><p>难题上长度有用。应按难度分桶看「准确率 vs token」。只压平均长度会伤害难题桶。这与 <a href="/llm/rl-difficulty-curriculum">难度课程</a> 的分桶报告同一纪律。</p><p><span class="marginnote">产品投诉「太啰嗦」往往是过度思考 + 混合模式失败，不是 RM 爱长的文本助手病，虽然外观相似。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>诊断：分桶帕累托；重复 n-gram；答案首次出现位置 vs 结束位置。抑制：混合路由；过长软惩罚对简单题更狠（按估计难度调 \\(L\\)）；在 \\(R\\) 里加「首次正确后继续写」的惩罚需小心——没有在线校验器时无法知道首次正确。可用：训练时对已知易题设短 \\(B\\)。推理：早停规则（答案稳定）。</p>',11)),(e(),s(h,null,{default:r(()=>[d(l,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20TD%0A%20%20EASY%5B%22%E6%98%93%E9%A2%98%22%5D%20--%3E%20LONG%5B%22%E4%BB%8D%E9%95%BF%E9%93%BE%22%5D%0A%20%20LONG%20--%3E%20GAIN%5B%22%E5%87%86%E7%A1%AE%E7%8E%87%E5%A2%9E%E7%9B%8A%E2%89%880%22%5D%0A%20%20GAIN%20--%3E%20OV%5B%22%E8%BF%87%E5%BA%A6%E6%80%9D%E8%80%83%22%5D%0A%20%20OV%20--%3E%20MIX%5B%22%E6%94%B9%E8%B5%B0%E7%9F%AD%E6%A8%A1%E5%BC%8F%22%5D%0A%20%20OV%20--%3E%20PEN%5B%22%E6%98%93%E9%A2%98%E7%9F%AD%E9%A2%84%E7%AE%97%20%2F%20%E8%BD%AF%E6%83%A9%E7%BD%9A%22%5D%0A"})]),fallback:r(()=>[...a[0]||(a[0]=[p(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<p>与 <a href="/llm/entropy-collapse">熵塌</a> 对照：过度思考时熵可以不低（一直在说新的废话）。看的是<strong>对准确率无贡献的尾部长度</strong>。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>可验证 RL 的最优策略在 \\(R\\in\\{0,1\\}\\) 下不唯一：所有做对的长度都同分。训练噪声与「长链曾经救命」使质量偏向长。要挑短的对，必须改偏序：同样正确时偏短。这是多目标，不是改校验器。</p><p><span class="marginnote">强迫短预算在难題上会制造截断错误，表现为过度思考的反面。分桶调 \\(B\\)。</span></p><h2 id="边界与工程取舍" tabindex="-1">边界与工程取舍 <a class="header-anchor" href="#边界与工程取舍" aria-label="Permalink to &quot;边界与工程取舍&quot;">​</a></h2><p>没有难度估计时，不要全局压长度。用基座或当前模型的通过率当难度代理，比题面星级更跟得上策略。下一课把「偏短」写成可控的长度目标，而不是只骂啰嗦。</p><p>按难度分桶看准确率–token。全局压平均长度会伤害难题桶；空转复核与答案翻转不是同一件事。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>过度思考是对错奖励下长度无价格、简单题尾部 token 零增益。</li><li>必须按难度分桶看准确率–token，不能只压平均长度。</li><li>抑制：混合模式、易题短预算、正确则偏短的多目标。</li><li>与有用回溯的差别：答案是否改变。</li><li>出处：Chen 等过度思考测量；DeepSeek-AI R1 长度现象；Yu 等超长塑形作工具。</li></ul>',9))])}const D=i(E,[["render",c]]);export{B as __pageData,D as default};
